CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('super_admin','content_admin','email_admin','prayer_admin','testimony_moderator','ministry_admin','member')),active BOOLEAN NOT NULL DEFAULT TRUE,email_verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public_content(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',content_type TEXT NOT NULL DEFAULT 'page',slug TEXT NOT NULL UNIQUE,published BOOLEAN NOT NULL DEFAULT FALSE,published_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS events(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ,location TEXT NOT NULL DEFAULT '',slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sermons(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,preacher TEXT NOT NULL DEFAULT '',sermon_date DATE,scripture_reference TEXT NOT NULL DEFAULT '',media_url TEXT,summary TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS testimonies(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,display_name TEXT,body TEXT NOT NULL,consent BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','unpublished')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),reviewed_at TIMESTAMPTZ,reviewed_by BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS prayer_requests(id BIGSERIAL PRIMARY KEY,name TEXT,contact TEXT,body TEXT NOT NULL,follow_up_consent BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','assigned','in_progress','closed')),assigned_to BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contact_messages(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS volunteers(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,interest TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS visitors(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,contact TEXT,visit_date DATE,follow_up_consent BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'new',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS newsletter_subscribers(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,consent_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','subscribed','unsubscribed','bounced')),events BOOLEAN NOT NULL DEFAULT TRUE,sermons BOOLEAN NOT NULL DEFAULT TRUE,monthly BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_events_status_date ON events(status,starts_at);
CREATE INDEX IF NOT EXISTS idx_sermons_status_date ON sermons(status,sermon_date);
CREATE INDEX IF NOT EXISTS idx_testimonies_review ON testimonies(status,created_at);
CREATE INDEX IF NOT EXISTS idx_prayer_status ON prayer_requests(status,created_at);
